export function getOfficialEnglishPeriod(
  grade: Grade | number,
  week: number,
  periodInWeek: number = 1
): OfficialEnglishPeriod | undefined {
  const gNum = Number(grade);
  const pInW = Math.max(1, Math.min(4, periodInWeek));
  const pYear = (week - 1) * 4 + pInW;
  return ALL_GRADES_ENGLISH_CURRICULUM.find(
    (p) => p.grade === gNum && p.periodInYear === pYear
  ) || ALL_GRADES_ENGLISH_CURRICULUM.find(
    (p) => p.grade === gNum && p.week === week && p.periodInWeek === pInW
  );
}

export function getOfficialEnglishPeriodByYear(
  grade: Grade | number,
  periodInYear: number
): OfficialEnglishPeriod | undefined {
  const gNum = Number(grade);
  return ALL_GRADES_ENGLISH_CURRICULUM.find(
    (p) => p.grade === gNum && p.periodInYear === periodInYear
  );
}

export function getWeeklyEnglishPeriods(
  grade: Grade | number,
  week: number
): OfficialEnglishPeriod[] {
  const gNum = Number(grade);
  return ALL_GRADES_ENGLISH_CURRICULUM.filter(
    (p) => p.grade === gNum && p.week === week
  );
}
